#include <iostream>
#include <array>
using namespace std;

int n, m;
pair<char, char> p[100];
char ch[100000];
array<char, 256> mapping;

void initialize_mapping() {
    mapping.fill(-1); // default to -1 (no change)
    for (int i = 0; i < n; i++) {
        mapping[p[i].first] = p[i].second; // direct mapping
    }
}

int main() {
    while (cin >> n && n > 0) {
        for (int i = 0; i < n; i++) {
            cin >> p[i].first >> p[i].second;
        }
        initialize_mapping();
        cin >> m;
        for (int i = 0; i < m; i++) {
            cin >> ch[i];
            if (mapping[ch[i]] != -1) {
                ch[i] = mapping[ch[i]]; // apply mapping if exists
            }
        }
        for (int i = 0; i < m; i++)
            cout << ch[i];
        cout << endl;
    }
    return 0;
}

