#include <iostream>
#include <unordered_map>
using namespace std;

int n, m;
unordered_map<char, char> mapping;

void initialize_mapping() {
    for (int i = 0; i < 256; i++) {
        mapping[i] = i; // identity mapping
    }
    char key, value;
    for (int i = 0; i < n; i++) {
        cin >> key >> value;
        mapping[key] = value; // Store pairs in a hashmap for O(1) access
    }
}

int main() {
    while (cin >> n && n > 0) {
        initialize_mapping();
        cin >> m;
        string ch(m, ' '); // Initialize a string of size m
        for (int i = 0; i < m; i++) {
            char c;
            cin >> c;
            ch[i] = mapping.count(c) ? mapping[c] : c; // Use the hashmap for direct lookup
        }
        cout << ch << endl; // Output the transformed string directly
    }
    return 0;
}

